  /** Per-group membership signature (group key → sorted member keys), for the merged path. */
  private builtGroupSigs = new Map<string, string>();

  /**
   * Rebuild the (ring, material) groups whose membership has changed
   * (merge path). Groups whose membership hasn't changed keep their
   * merged mesh — during streaming, most frames only touch one or two
   * rings. Discarded groups (empty membership) have their merged
   * geometry disposed.
   */
  private rebuildRingMeshes(): void {
    const groups = new Map<string, Array<{ entry: CachedChunk; ring: LodRing; biome: Biome | null }>>();
    for (const [key, info] of this.mounted) {
      const entry = this.streamer.getCached(key);
      if (!entry) continue;
      const gk = `${info.ring}:${info.biome ?? 'far'}`;
      const list = groups.get(gk);
      if (list) list.push({ entry, ...info });
      else groups.set(gk, [{ entry, ...info }]);
    }

    // Discard groups that are no longer mounted.
    for (const gk of this.builtGroupSigs.keys()) {
      if (!groups.has(gk)) {
        const mesh = this.meshes.get(gk)!;
        this.group.remove(mesh);
        mesh.geometry.dispose();
        this.meshes.delete(gk);
        this.builtGroupSigs.delete(gk);
      }
    }

    for (const [gk, members] of groups) {
      const sig = members.map((m) => m.entry.key).sort().join(',');
      if (this.builtGroupSigs.get(gk) === sig) continue; // no membership change
      const prev = this.meshes.get(gk);
      if (prev) {
        this.group.remove(prev);
        prev.geometry.dispose();
        this.meshes.delete(gk);
      }
      const [, biomeKey] = gk.split(':') as [string, string];
      const biome = biomeKey === 'far' ? null : (biomeKey as Biome);
      const translated = members.map(({ entry, ring }) => {
        const src = ringGeometry(entry, ring)!;
        const copy = src.clone();
        copy.translate(entry.chunkX * 320, 0, entry.chunkZ * 320);
        return copy;
      });
      const geometry = mergeGeometries(translated, false)!;
      for (const copy of translated) copy.dispose();
      const mesh = new THREE.Mesh(geometry, this.materialFor(biome));
      mesh.frustumCulled = true;
      this.group.add(mesh);
      this.meshes.set(gk, mesh);
      this.builtGroupSigs.set(gk, sig);
    }
    this.builtSignature = signatureFor(this.mounted);
  }
